42	// vueCorpusTypes accepts a relation type written as one string or a list.
43	type vueCorpusTypes []string
44	
45	func (t *vueCorpusTypes) UnmarshalJSON(data []byte) error {
46		var one string
47		if err := json.Unmarshal(data, &one); err == nil {
48			*t = vueCorpusTypes{one}
49			return nil
50		}
51		var many []string
52		if err := json.Unmarshal(data, &many); err != nil {
53			return fmt.Errorf("relation type must be a string or a list of strings: %w", err)
54		}
55		*t = many
56		return nil
57	}
