124	// TestVueCorpusManifestMatchesSource keeps the ground truth honest: every fact
125	// names a real file, every symbol is declared on its stated line, every trap in
126	// absent_symbols exists in source, and every named relation endpoint is itself
127	// an expected symbol.
128	func TestVueCorpusManifestMatchesSource(t *testing.T) {
129		supported := map[string]bool{}
130		for _, relation := range Capabilities().SupportedRelationTypes {
131			supported[relation] = true
132		}
133		for _, app := range vueCorpusApps {
134			t.Run(app, func(t *testing.T) {
135				manifest := loadVueCorpusManifest(t, app)
136				if manifest.App != app {
137					t.Errorf("manifest app = %q, want %q", manifest.App, app)
138				}
139				sources := map[string][]string{}
140				readLines := func(file string) ([]string, bool) {
141					if lines, ok := sources[file]; ok {
142						return lines, true
143					}
144					data, err := os.ReadFile(filepath.Join(vueCorpusRoot, app, filepath.FromSlash(file)))
145					if err != nil {
146						t.Errorf("%s: %v", file, err)
147						return nil, false
148					}
149					lines := strings.Split(string(normalizeFixtureData(data)), "\n")
150					sources[file] = lines
151					return lines, true
152				}
153				declared := map[string]bool{}
154				seen := map[string]bool{}
155				for _, symbol := range manifest.Symbols {
156					key := vueCorpusSymbolKey(symbol.File, symbol.Name, symbol.Kind)
157					if seen[key] {
158						t.Errorf("duplicate symbol %s", key)
159					}
160					seen[key] = true
161					if !vueCorpusTags[symbol.Tag] {
162						t.Errorf("%s: unknown tag %q", key, symbol.Tag)
163					}
164					declared[symbol.File+"#"+symbol.Name] = true
165					declared[symbol.File+"#"+symbol.Name+":"+symbol.Kind] = true
166					lines, ok := readLines(symbol.File)
167					if !ok {
168						continue
169					}
170					if symbol.Line < 1 || symbol.Line > len(lines) {
171						t.Errorf("%s: line %d is outside the file (%d lines)", key, symbol.Line, len(lines))
172						continue
173					}
174					// A .vue file's component and document symbols span the whole
175					// file and take its base name, which no source line declares.
176					base := strings.TrimSuffix(filepath.Base(symbol.File), ".vue")
177					if strings.HasSuffix(symbol.File, ".vue") && symbol.Name == base && (symbol.Kind == "component" || symbol.Kind == "document") {
178						if symbol.Line != 1 {
179							t.Errorf("%s: a file-level %s symbol starts on line 1, not %d", key, symbol.Kind, symbol.Line)
180						}
181						continue
182					}
183					pattern := regexp.MustCompile(`(^|[^A-Za-z0-9_$])` + regexp.QuoteMeta(symbol.Name) + `([^A-Za-z0-9_$]|$)`)
184					if !pattern.MatchString(lines[symbol.Line-1]) {
185						t.Errorf("%s: line %d does not declare the name: %q", key, symbol.Line, lines[symbol.Line-1])
186					}
187				}
188				for _, absent := range manifest.AbsentSymbols {
189					if !vueCorpusTags[absent.Tag] || absent.Why == "" {
190						t.Errorf("absent %s#%s needs a known tag and a why", absent.File, absent.Name)
191					}
192					lines, ok := readLines(absent.File)
193					if ok && !strings.Contains(strings.Join(lines, "\n"), absent.Name) {
194						t.Errorf("absent %s#%s: the name never appears in the file, so the trap is not real", absent.File, absent.Name)
195					}
196				}
197				for _, relation := range manifest.Relations {
198					key := relation.key()
199					if seen[key] {
200						t.Errorf("duplicate relation %s", key)
201					}
202					seen[key] = true
203					if !vueCorpusTags[relation.Tag] {
204						t.Errorf("%s: unknown tag %q", key, relation.Tag)
205					}
206					if len(relation.Type) == 0 {
207						t.Errorf("%s: missing type", key)
208					}
209					for _, relationType := range relation.Type {
210						if !supported[relationType] {
211							t.Errorf("%s: %q is not a supported relation type", key, relationType)
212						}
213					}
214					for _, endpoint := range []vueCorpusEndpoint{relation.From, relation.To} {
215						if (endpoint.External == "") == (endpoint.File == "") {
216							t.Errorf("%s: endpoint needs exactly one of file or external", key)
217							continue
218						}
219						if endpoint.External != "" {
220							continue
221						}
222						if _, ok := readLines(endpoint.File); !ok {
223							continue
224						}
225						if endpoint.Name != "" && !declared[endpoint.File+"#"+endpoint.Name] {
226							t.Errorf("%s: endpoint %s is not listed in symbols", key, endpoint.key())
227						}
228						if endpoint.Name != "" && endpoint.Kind != "" && !declared[endpoint.File+"#"+endpoint.Name+":"+endpoint.Kind] {
229							t.Errorf("%s: endpoint %s has no symbols entry with that kind", key, endpoint.key())
230						}
231					}
232				}
233			})
234		}
235	}
236	
237	type vueCorpusTagScore struct {
238		Found int `json:"found"`
239		Total int `json:"total"`
240	}
241	
242	type vueCorpusAppScore struct {
243		Found      int                          `json:"found"`
244		Total      int                          `json:"total"`
245		Tags       map[string]vueCorpusTagScore `json:"tags"`
246		FoundFacts []string                     `json:"found_facts"`
247		Missing    map[string][]string          `json:"-"`
248	}
249	
250	func scoreVueCorpusApp(t *testing.T, app string) vueCorpusAppScore {
251		t.Helper()
252		manifest := loadVueCorpusManifest(t, app)
253		dir := filepath.Join(t.TempDir(), app)
254		copyFixtureTree(t, filepath.Join(vueCorpusRoot, app), dir)
255		snapshot, err := BuildProviderSnapshotWithOptions(t.Context(), dir, "0.0.0-test", ProviderSnapshotOptions{Worktree: true})
256		if err != nil {
257			t.Fatal(err)
258		}
259	
260		symbolsByFile := map[string][]SymbolRecord{}
261		for _, symbol := range snapshot.Symbols {
262			symbolsByFile[symbol.FilePath] = append(symbolsByFile[symbol.FilePath], symbol)
263		}
264		fileIDs := map[string]string{}
265		for _, file := range snapshot.Files {
266			fileIDs[file.Path] = file.ID
267		}
268		externalIDs := map[string][]string{}
269		for _, external := range snapshot.Externals {
270			externalIDs[external.Value] = append(externalIDs[external.Value], external.ID)
271		}
272		endpointIDs := func(endpoint vueCorpusEndpoint) map[string]bool {
273			ids := map[string]bool{}
274			switch {
275			case endpoint.External != "":
276				for _, id := range externalIDs[endpoint.External] {
277					ids[id] = true
278				}
279			case endpoint.Name == "":
280				if id, ok := fileIDs[endpoint.File]; ok {
281					ids[id] = true
282				}
283			default:
284				for _, symbol := range symbolsByFile[endpoint.File] {
285					if symbol.Name == endpoint.Name && (endpoint.Kind == "" || symbol.Kind == endpoint.Kind) {
286						ids[symbol.ID] = true
287					}
288				}
289			}
290			return ids
291		}
292	
293		score := vueCorpusAppScore{Tags: map[string]vueCorpusTagScore{}, Missing: map[string][]string{}}
294		record := func(tag, key string, found bool) {
295			tagScore := score.Tags[tag]
296			tagScore.Total++
297			score.Total++
298			if found {
299				tagScore.Found++
300				score.Found++
301				score.FoundFacts = append(score.FoundFacts, key)
302			} else {
303				score.Missing[tag] = append(score.Missing[tag], key)
304			}
305			score.Tags[tag] = tagScore
306		}
307		for _, symbol := range manifest.Symbols {
308			found := false
309			for _, candidate := range symbolsByFile[symbol.File] {
310				if candidate.Name == symbol.Name && (symbol.Kind == "" || candidate.Kind == symbol.Kind) &&
311					candidate.StartLine <= symbol.Line && symbol.Line <= max(candidate.EndLine, candidate.StartLine) {
312					found = true
313					break
314				}
315			}
316			record(symbol.Tag, vueCorpusSymbolKey(symbol.File, symbol.Name, symbol.Kind), found)
317		}
318		for _, absent := range manifest.AbsentSymbols {
319			emitted := false
320			for _, candidate := range symbolsByFile[absent.File] {
321				if candidate.Name == absent.Name && (absent.Kind == "" || candidate.Kind == absent.Kind) {
322					emitted = true
323					break
324				}
325			}
326			record(absent.Tag, "absent "+absent.File+"#"+absent.Name, !emitted)
327		}
328		for _, relation := range manifest.Relations {
329			types := map[string]bool{}
330			for _, relationType := range relation.Type {
331				types[relationType] = true
332			}
333			from, to := endpointIDs(relation.From), endpointIDs(relation.To)
334			found := false
335			for _, candidate := range snapshot.Relations {
336				if types[candidate.Type] && from[candidate.FromID] && to[candidate.ToID] {
337					found = true
338					break
339				}
340			}
341			record(relation.Tag, "relation "+relation.key(), found)
342		}
343		sort.Strings(score.FoundFacts)
344		return score
345	}
346	
347	// TestVueCorpusScore ratchets corpus coverage. It fails when a previously found
348	// fact disappears, and also when new facts appear, so each improvement is
349	// recorded in score.json by rerunning with -update.
350	func TestVueCorpusScore(t *testing.T) {
351		scorePath := filepath.Join(vueCorpusRoot, "score.json")
352		got := map[string]vueCorpusAppScore{}
353		for _, app := range vueCorpusApps {
354			got[app] = scoreVueCorpusApp(t, app)
355		}
356	
357		var report strings.Builder
358		for _, app := range vueCorpusApps {
359			score := got[app]
360			fmt.Fprintf(&report, "%s: %d/%d facts\n", app, score.Found, score.Total)
361			tags := make([]string, 0, len(score.Tags))
362			for tag := range score.Tags {
363				tags = append(tags, tag)
364			}
365			sort.Strings(tags)
366			for _, tag := range tags {
367				fmt.Fprintf(&report, "  %-20s %3d/%-3d\n", tag, score.Tags[tag].Found, score.Tags[tag].Total)
368			}
369		}
370		t.Log("\n" + report.String())
371		for _, app := range vueCorpusApps {
372			// baseline facts are ones the provider emits today; losing one is a
373			// regression, and listing one it never emitted is a manifest error.
374			if missing := got[app].Missing["baseline"]; len(missing) > 0 {
375				t.Errorf("%s: %d baseline facts are not emitted:\n  %s", app, len(missing), strings.Join(missing, "\n  "))
376			}
377			if os.Getenv("VUE_CORPUS_VERBOSE") != "" {
378				tags := make([]string, 0, len(got[app].Missing))
379				for tag := range got[app].Missing {
380					tags = append(tags, tag)
381				}
382				sort.Strings(tags)
383				for _, tag := range tags {
384					t.Logf("%s missing [%s]:\n  %s", app, tag, strings.Join(got[app].Missing[tag], "\n  "))
385				}
386			}
387		}
388	
389		if *updateGolden {
390			data, err := json.MarshalIndent(got, "", "  ")
391			if err != nil {
392				t.Fatal(err)
393			}
394			if err := os.WriteFile(scorePath, append(data, '\n'), 0o644); err != nil {
395				t.Fatal(err)
396			}
397			return
398		}
399		data, err := os.ReadFile(scorePath)
400		if err != nil {
401			t.Fatalf("read %s (run with -update to create): %v", scorePath, err)
402		}
403		var want map[string]vueCorpusAppScore
404		if err := json.Unmarshal(data, &want); err != nil {
405			t.Fatalf("parse %s: %v", scorePath, err)
406		}
407		for _, app := range vueCorpusApps {
408			before := map[string]bool{}
409			for _, fact := range want[app].FoundFacts {
410				before[fact] = true
411			}
412			now := map[string]bool{}
413			for _, fact := range got[app].FoundFacts {
414				now[fact] = true
415			}
416			var lost, gained []string
417			for fact := range before {
418				if !now[fact] {
419					lost = append(lost, fact)
420				}
421			}
422			for fact := range now {
423				if !before[fact] {
424					gained = append(gained, fact)
425				}
426			}
427			sort.Strings(lost)
428			sort.Strings(gained)
429			if len(lost) > 0 {
430				t.Errorf("%s regressed: %d previously found facts are missing:\n  %s", app, len(lost), strings.Join(lost, "\n  "))
431			}
432			if len(gained) > 0 {
433				t.Errorf("%s improved by %d facts; record it with:\n\tgo test ./internal/sem -run TestVueCorpusScore -update\n  %s", app, len(gained), strings.Join(gained, "\n  "))
434			}
435			if want[app].Total != got[app].Total {
436				t.Errorf("%s manifest changed (%d facts, score.json has %d); rerun with -update", app, got[app].Total, want[app].Total)
437			}
438		}
439	}
