    tasks.value = tasks.value.filter((task) => task.id !== taskId)
    bus.emit('task:deleted', taskId)
  }

  async function moveTask(payload: TaskMovedPayload) {
    const task = findTask(payload.taskId)
    if (!task) {
      return
    }
    const previous = { columnId: task.columnId, position: task.position }
    task.columnId = payload.toColumnId
    task.position = payload.position
    try {
      await postTaskMove(payload)
    } catch {
      Object.assign(task, previous)
    }
  }

  return { tasks, loading, error, tasksByColumn, findTask, loadTasks, addTask, editTask, removeTask, moveTask }
})

import { defineStore } from 'pinia'
import { fetchSession, postLogin, postLogout } from '@/api/auth'
import { setAuthToken } from '@/api/client'
import { isPrivileged, type Credentials, type Session, type User } from '@/types/user'

interface AuthState {
  session: Session | null
  restoring: boolean
  lastError: string | null
}

export const useAuthStore = defineStore('auth', {
  state: (): AuthState => ({
    session: null,
    restoring: false,
    lastError: null,
  }),
  getters: {
    isAuthenticated: (state): boolean => state.session !== null,
    currentUser: (state): User | null => state.session?.user ?? null,
    isAdmin(): boolean {
      return isPrivileged(this.currentUser)
    },
  },
  actions: {
    async login(credentials: Credentials) {
      this.lastError = null
      try {
        const session = await postLogin(credentials)
        this.applySession(session)
      } catch (err) {
        this.lastError = err instanceof Error ? err.message : 'Login failed'
        throw err
      }
    },
    async logout() {
      await postLogout()
      this.applySession(null)
    },
    async restoreSession() {
      this.restoring = true
      try {
        this.applySession(await fetchSession())
      } finally {
        this.restoring = false
      }
    },
    applySession(session: Session | null) {
      this.session = session
      setAuthToken(session?.token ?? null)
    },
  },
})

import { defineStore } from 'pinia'
import { computed, ref } from 'vue'
import { fetchBoard, fetchMembers, fetchProjects } from '@/api/projects'
import type { Board, Project } from '@/types/project'
import type { User } from '@/types/user'

export const useProjectStore = defineStore('projects', () => {
  const projects = ref<Project[]>([])
  const currentProjectId = ref<string | null>(null)
  const board = ref<Board | null>(null)
  const members = ref<User[]>([])

  const currentProject = computed(() => projects.value.find((project) => project.id === currentProjectId.value) ?? null)
  const activeProjects = computed(() => projects.value.filter((project) => !project.archived))

  async function loadProjects() {
    projects.value = await fetchProjects()
  }

  async function selectProject(projectId: string) {
    currentProjectId.value = projectId
    const project = currentProject.value
    if (!project) {
      return
    }
    const [loadedBoard, loadedMembers] = await Promise.all([fetchBoard(project.boardId), fetchMembers(projectId)])
    board.value = loadedBoard
    members.value = loadedMembers
  }

  function memberById(userId: string): User | undefined {
    return members.value.find((member) => member.id === userId)
  }

  return { projects, currentProjectId, board, members, currentProject, activeProjects, loadProjects, selectProject, memberById }
})

import { defineStore } from 'pinia'

export type Theme = 'light' | 'dark'

export type Density = 'comfortable' | 'compact'

export const useSettingsStore = defineStore('settings', {
  state: () => ({
    theme: 'light' as Theme,
    density: 'comfortable' as Density,
    showCompleted: true,
    pageSize: 20,
  }),
  getters: {
    isDark: (state) => state.theme === 'dark',
  },
  actions: {
    toggleTheme() {
      this.theme = this.theme === 'light' ? 'dark' : 'light'
    },
    setDensity(density: Density) {
      this.density = density
    },
    setPageSize(size: number) {
      this.pageSize = Math.max(5, Math.min(100, size))
    },
  },
})

